package localchat;
import java.nio.file.*;import java.nio.file.attribute.*;import java.util.*;import javax.swing.*;
public final class HotfolderTest {
 static int checks;static void check(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}
 static Path put(Path path,String text)throws Exception{Files.createDirectories(path.getParent());Files.writeString(path,text);return path;}
 public static void main(String[] args)throws Exception{
  Path home=Files.createTempDirectory(Files.createDirectories(Path.of(System.getProperty("localchat.home"))),"run-");Path root=Files.createDirectories(home.resolve("PRODUCTIE"));Path state=home.resolve("hotfolder.json");Path existing=put(root.resolve("507045/first.msg"),"old");Hotfolder watcher=new Hotfolder(state,30);
  check(watcher.scan(root,0).isEmpty(),"first enable inventories old projects without drafts");
  put(root.resolve("506946/new.msg"),"first part");check(watcher.scan(root,10).isEmpty(),"new source settles before draft");put(root.resolve("506946/new.msg"),"second part changed");check(watcher.scan(root,35).isEmpty(),"ongoing copy resets settle");check(watcher.scan(root,60).isEmpty(),"not stable long enough");var changes=watcher.scan(root,70);check(changes.size()==1&&changes.get(0).fresh()&&changes.get(0).project().equals("506946"),"stable new project detected");Hotfolder.Change added=changes.get(0);check(Hotfolder.prompt(added).contains(added.folder().toString())&&Hotfolder.prompt(added).contains("PROJECT_INFO.md"),"exact path avoids PRODUCTIE PRODUCTIE ambiguity");check(watcher.scan(root,75).size()==1,"unacknowledged draft creation can retry");watcher.acknowledge(added);check(watcher.scan(root,80).isEmpty(),"successful draft acknowledged once");
  watcher=new Hotfolder(state,30);check(watcher.scan(root,100).isEmpty(),"restart has no duplicate draft");put(existing,"new email revision");watcher.scan(root,110);var update=watcher.scan(root,145);check(update.size()==1&&!update.get(0).fresh()&&update.get(0).files().equals(List.of("first.msg")),"existing project gets continuation");watcher.acknowledge(update.get(0));String signature=update.get(0).signature();put(existing,"a later revision under same filename");watcher.scan(root,150);var next=watcher.scan(root,185);check(!next.get(0).signature().equals(signature),"same filename future revisions have distinct event IDs");watcher.acknowledge(next.get(0));
  put(root.resolve("507045/Controle/PDFCONTROL/RAPPORT.pdf"),"generated report");put(root.resolve("507045/PROJECT_INFO.md"),"journal");put(root.resolve("507045/~$lock.xlsx"),"lock");put(root.resolve("not-a-project/file.msg"),"other");check(watcher.scan(root,200).isEmpty()&&watcher.scan(root,250).isEmpty(),"reports, journals, locks and unrelated folders do not loop");put(root.resolve("507045/DWG/new.dwg"),"new drawing");watcher.scan(root,260);var dwg=watcher.scan(root,300);check(dwg.size()==1,"nested standard source folder is watched");watcher.acknowledge(dwg.get(0));
  put(root.resolve("507045/Controle/Atasamente/new.eml"),"new source email");watcher.scan(root,301);var nested=watcher.scan(root,335);check(nested.size()==1,"source attachments inside Controle remain monitored");watcher.acknowledge(nested.get(0));
  Files.delete(existing);watcher.scan(root,340);check(watcher.scan(root,380).isEmpty(),"deletion alone is not a new-email instruction");
  check(ProjectStatus.valid(null).equals("draft")&&ProjectStatus.valid("forged").equals("draft"),"legacy and unknown status migration safe");for(String value:ProjectStatus.VALUES){var s=new Conversations.State();s.projectStatus=value;s.hotfolderProject="fixture";s.hotfolderEvent="event";s.unread=true;var loaded=Conversations.State.fromJson(s.toJson(),0);check(loaded.projectStatus.equals(value)&&loaded.unread&&loaded.hotfolderProject.equals("fixture"),"status and notification persisted "+value);}
  LocalChat[] app={null};try(var server=new FeatureTest.Server(FeatureTest.json(FeatureTest.answer("not called",1,1)))){
   FeatureTest.edt(()->{app[0]=AttachmentTest.window(home.resolve("app"),server.url());AttachmentTest.input(app[0]).setText("my active pending message");FeatureTest.call(app[0],"createHotfolderDraft",new Class<?>[]{Hotfolder.Change.class},added);FeatureTest.call(app[0],"createHotfolderDraft",new Class<?>[]{Hotfolder.Change.class},added);var chats=Conversations.list(home.resolve("app/conversatii"));check(chats.size()==1&&chats.get(0).messages().isEmpty()&&chats.get(0).state().unread,"one draft without messages, duplicate callback idempotent");check(chats.get(0).state().systemPrompt!=null&&chats.get(0).workDir().equals(added.folder().toString())&&Boolean.TRUE.equals(chats.get(0).state().toolsEnabled),"draft bound to exact project and MBS");check(AttachmentTest.input(app[0]).getText().equals("my active pending message")&&server.requests.isEmpty(),"watcher preserves active draft with zero inference");var second=new Hotfolder.Change(added.project(),added.folder(),false,List.of("second.msg"),"second-event");FeatureTest.call(app[0],"createHotfolderDraft",new Class<?>[]{Hotfolder.Change.class},second);chats=Conversations.list(home.resolve("app/conversatii"));check(chats.size()==1&&chats.get(0).state().draft.contains("second.msg"),"multiple additions grouped in unopened draft");FeatureTest.call(app[0],"refreshSessions",new Class<?>[]{});WorkspacePanel sidebar=FeatureTest.field(app[0],"workspace");check(sidebar.notifications.getText().equals("1"),"notification bell carries unread count");sidebar.search.setText("no matching title");FeatureTest.call(sidebar,"selectAndOpen",new Class<?>[]{Conversations.Saved.class},chats.get(0));check(!AttachmentTest.state(app[0]).unread&&server.requests.isEmpty(),"opening draft clears unread without API");FeatureTest.call(app[0],"changeProjectStatus",new Class<?>[]{String.class},"completed");check(Conversations.load(FeatureTest.field(app[0],"conversationFile")).state().projectStatus.equals("completed"),"manual finalization persisted");for(String code:I18n.CODES){I18n.setLanguage(code);for(String value:ProjectStatus.VALUES)check(!ProjectStatus.label(value).isBlank(),"localized status "+code+value);}app[0].dispose();});
  }finally{FeatureTest.edt(()->{for(var w:java.awt.Window.getWindows())w.dispose();});}
  System.out.println("PASS: "+checks+" hotfolder, status, draft and notification checks; no API or production modifications");System.exit(0);
 }
}
